onClick:
{{
  Table_ein.selectedRow.sid != null && Table_ein.selectedRow.sid !== ""
    ? update_rs_einnahme.run()
        .then(() => insertEinnahme.run())
        .then(() => {
            monatsliste_ein.run();
            showAlert('Einnahme aktualisiert ✅', 'success');
            removeValue("");
        })
        .catch(() => showAlert('Fehler beim Aktualisieren ❌', 'error'))
    : insertEinnahme.run()
        .then(() => {
            monatsliste_ein.run();
            showAlert('Einnahme gespeichert ✅', 'success');
            removeValue("");
        })
        .catch(() => showAlert('Fehler beim Speichern ❌', 'error'))
}}
